import bpy, math
from collections import deque

# Analyze the three reference images: sizes + connected components of non-background pixels
paths = [f"/app/input/render_000{i}.png" for i in range(3)]
for p in paths:
    img = bpy.data.images.load(p, check_existing=True)
    W, H = img.size
    print(p, W, H)
    px = list(img.pixels[:])  # RGBA float, bottom-up rows
    step = 4
    gw, gh = W//step, H//step
    mask = [[False]*gw for _ in range(gh)]
    for gy in range(gh):
        for gx in range(gw):
            x = gx*step + step//2; y = gy*step + step//2
            i = (y*W + x)*4
            r,g,b = px[i],px[i+1],px[i+2]
            # background is near-white
            if (1.0-r)+(1.0-g)+(1.0-b) > 0.18:
                mask[gy][gx] = True
    seen = [[False]*gw for _ in range(gh)]
    comps = []
    for gy in range(gh):
        for gx in range(gw):
            if mask[gy][gx] and not seen[gy][gx]:
                q = deque([(gx,gy)]); seen[gy][gx]=True
                xs=[]; ys=[]
                while q:
                    cx,cy = q.popleft(); xs.append(cx); ys.append(cy)
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny = cx+dx, cy+dy
                        if 0<=nx<gw and 0<=ny<gh and mask[ny][nx] and not seen[ny][nx]:
                            seen[ny][nx]=True; q.append((nx,ny))
                if len(xs) >= 6:
                    comps.append((len(xs), min(xs)*step, (max(xs)+1)*step, H-(max(ys)+1)*step, H-min(ys)*step))
    comps.sort(reverse=True)
    print(f"  {len(comps)} components (size, x0,x1, y_top,y_bot in top-origin px):")
    for c in comps[:30]:
        print("   ", c)

import numpy as np
