W=H=768
fov = np.radians(39.6); tanf = np.tan(fov/2)
cams = {
 0: (np.array([-5.6,-6.2,2.4]), np.array([0.6242,0.7579,-0.1895]), np.array([0.1205,0.1463,0.9819])),
 1: (np.array([5.6,-6.2,2.4]),  np.array([-0.6242,0.7579,-0.1895]),np.array([-0.1205,0.1463,0.9819])),
 2: (np.array([5.4,7.0,2.6]),   np.array([-0.6289,-0.7453,-0.2213]),np.array([-0.1427,-0.1691,0.9752])),
}
cam_mats={}
for k,(pos,d,up) in cams.items():
    d=d/np.linalg.norm(d); r=np.cross(d,up); r/=np.linalg.norm(r); u=np.cross(r,d)
    cam_mats[k]=(pos,r,u,d)

def box_bbox(cam_id, cx, cy, sx, sy, h, yaw=0.0, z0=0.0):
    pos,r,u,d = cam_mats[cam_id]
    pts=[]; c,s=np.cos(yaw),np.sin(yaw)
    for dx in (-sx/2,sx/2):
        for dy in (-sy/2,sy/2):
            for dz in (z0,z0+h):
                p=np.array([cx+dx*c-dy*s, cy+dx*s+dy*c, dz])
                v=p-pos; z=v@d
                px=(v@r)/(z*tanf); py=(v@u)/(z*tanf)
                pts.append(((px+1)/2*W,(1-py)/2*H))
    xs=[a for a,_ in pts]; ys=[b for _,b in pts]
    return min(xs),min(ys),max(xs),max(ys)

def fit(name, cams_boxes, sx, sy, h, yaw=0.0, z0=0.0, xr=None, yr=None, clip_ok=()):
    if xr is None: xr=(-4,5,0.05)
    if yr is None: yr=(-4,6,0.05)
    best=None
    for cx in np.arange(*xr):
        for cy in np.arange(*yr):
            err=0
            for cid,(tx0,ty0,tx1,ty1) in cams_boxes.items():
                bx0,by0,bx1,by1 = box_bbox(cid,cx,cy,sx,sy,h,yaw,z0)
                ex0=0 if 'l' in clip_ok and bx0<=tx0 else (bx0-tx0)
                ex1=0 if 'r' in clip_ok and bx1>=tx1 else (bx1-tx1)
                err+=ex0**2+(by0-ty0)**2+ex1**2+(by1-ty1)**2
            if best is None or err<best[0]: best=(err,cx,cy)
    print(f"{name}: center=({best[1]:+.2f},{best[2]:+.2f}) err={best[0]:.0f}")
    for cid,t in cams_boxes.items():
        b=box_bbox(cid,best[1],best[2],sx,sy,h,yaw,z0)
        print(f"   cam{cid}: pred=({b[0]:.0f},{b[1]:.0f},{b[2]:.0f},{b[3]:.0f}) target={t}")
    return best[1],best[2]

